/** Exercise the console's real enrollment UI against this run's temporary API state. */
export async function enrollConsoleOwner(
  page: Page,
  baseURL: string | undefined,
  metadata: Record<string, unknown>,
) {
  const stateDir = metadata.ownerStateDir;
  const apiPort = metadata.ownerApiPort;
  const consolePort = metadata.ownerConsolePort;
  if (
    typeof stateDir !== "string" ||
    typeof apiPort !== "number" ||
    !Number.isInteger(apiPort) ||
    apiPort < 1024 ||
    apiPort > 65535 ||
    !baseURL ||
    new URL(baseURL).origin !== `http://localhost:${consolePort}`
  )
    throw new Error("Missing isolated E2E project owner configuration");
  const relativeState = relative(await realpath(tmpdir()), await realpath(stateDir));
  if (!relativeState || relativeState.startsWith("..") || isAbsolute(relativeState))
    throw new Error("E2E owner material must belong to a temporary test directory");
  const signingKey = (await readFile(join(stateDir, "owner", "identity.key"), "utf8")).trim();
  const body = JSON.stringify({ intent: "recover" });
  const timestamp = String(Date.now());
  const nonce = randomBytes(16).toString("hex");
  const enrollment = await page.request.post(`http://127.0.0.1:${apiPort}${LOCAL_COMMAND_PATH}`, {
    headers: {
      "content-type": "application/json",
      "x-godseye-time": timestamp,
      "x-godseye-nonce": nonce,
      "x-godseye-proof": localProof(signingKey, body, timestamp, nonce),
    },
    data: body,
  });
  if (!enrollment.ok()) throw new Error(`E2E owner enrollment refused (${enrollment.status()})`);
  const { ticket } = (await enrollment.json()) as { ticket: string };
  const authenticator = await virtualOwnerAuthenticator(page);
  await page.goto(`${baseURL}/#enroll=${encodeURIComponent(ticket)}`);
  await page.getByRole("button", { name: "Enregistrer ma clé d’accès", exact: true }).click();
  await expect(page.getByRole("heading", { name: "Vue d’ensemble", exact: true })).toBeVisible();
  return authenticator;
}

export async function virtualOwnerAuthenticator(
  page: Page,
  transport: "internal" | "usb" = "internal",
) {
  const client = await page.context().newCDPSession(page);
  await client.send("WebAuthn.enable");
  const { authenticatorId } = await client.send("WebAuthn.addVirtualAuthenticator", {
    options: {
      protocol: "ctap2",
      transport,
      hasResidentKey: true,
      hasUserVerification: true,
      isUserVerified: true,
      automaticPresenceSimulation: true,
    },
  });
  return { client, authenticatorId };
}

export async function overrideUserVerification(
  authenticator: { client: CDPSession; authenticatorId: string },
  invalid: boolean,
) {
  await authenticator.client.send("WebAuthn.setResponseOverrideBits", {
    authenticatorId: authenticator.authenticatorId,
    isBadUV: invalid,
  });
}

// Browser-native toJSON serializes WebAuthn binary fields; these helpers perform no cryptography.
export async function registerOwnerPasskey(page: Page, ticket?: string, alteredOrigin?: string) {
  return page.evaluate(
    async ({ ticket, alteredOrigin }) => {
      const decode = (value: string) =>
        Uint8Array.from(atob(value.replace(/-/g, "+").replace(/_/g, "/")), (char) =>
          char.charCodeAt(0),
        );
      const query = ticket ? `?context=${encodeURIComponent(ticket)}` : "";
      const optionsResponse = await fetch(`/api/auth/passkey/generate-register-options${query}`);
      if (!optionsResponse.ok)
        return { status: optionsResponse.status, body: await optionsResponse.json() };
      const options = await optionsResponse.json();
      const credential = (await navigator.credentials.create({
        publicKey: PublicKeyCredential.parseCreationOptionsFromJSON(options),
      })) as PublicKeyCredential;
      const response = credential.toJSON() as RegistrationResponseJSON;
      if (alteredOrigin) {
        const clientData = JSON.parse(
          new TextDecoder().decode(decode(response.response.clientDataJSON)),
        );
        clientData.origin = alteredOrigin;
        response.response.clientDataJSON = btoa(JSON.stringify(clientData))
          .replace(/\+/g, "-")
          .replace(/\//g, "_")
          .replace(/=+$/, "");
      }
      const verified = await fetch("/api/auth/passkey/verify-registration", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ response, name: "Isolated browser passkey", createSession: true }),
      });
      return { status: verified.status, body: await verified.json() };
    },
    { ticket, alteredOrigin },
  );
}

export async function authenticateOwnerPasskey(page: Page) {
  return page.evaluate(async () => {
    const optionsResponse = await fetch("/api/auth/passkey/generate-authenticate-options");
    if (!optionsResponse.ok)
      return { status: optionsResponse.status, body: await optionsResponse.json() };
    const options = await optionsResponse.json();
    const credential = (await navigator.credentials.get({
      publicKey: PublicKeyCredential.parseRequestOptionsFromJSON(options),
    })) as PublicKeyCredential;
    const verified = await fetch("/api/auth/passkey/verify-authentication", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ response: credential.toJSON() }),
    });
    return {
      status: verified.status,
      body: await verified.json(),
      userVerification: options.userVerification,
    };
  });
}

export function browserOwnerRequest(page: Page, path: string, method = "GET") {
  return page.evaluate(
    async ({ path, method }) => {
      const response = await fetch(path, {
        method,
        ...(method === "POST"
          ? { headers: { "content-type": "application/json" }, body: "{}" }
          : {}),
      });
      return { status: response.status, body: await response.json() };
    },
    { path, method },
  );
}
